        "summary": "2006年版电视动画《魔法老师！？》改编自日本漫画家赤松健原作的漫画《魔法老师！》，由SHAFT和GANSIS共同制作。该版本在2006年10月4日至2007年3月28日期间在东京电视台播出，总共26集。2006年新版TV动画的故事内容可以说是独立于漫画版及2005年版本的，除了涅吉被梅尔帝亚纳魔法学校派往麻帆良学园实习的一段之外，其余的都和漫画版及2005年版本有很大情度的分别，在人物关系方面和学校方面都对当初的设定进行了不小的更改 [1] 。\n\n由于XEBEC制作的2005年版本引来各方批评，令赤松健和另一间动画公司SHAFT合作，首先推出的就是为再度改编成电视动画的《魔法老师！？》预热的OVA动画。由于OVA效果理想，所以2006年版亦是由SHAFT制作，而向来与SHAFT有合作关系的GANSIS亦加入。此次作品由号称“原作粉碎机”的新房昭之监督，令2006年的故事内容差不多完全独立于漫画版及2005年版本，“？”正是对新旧版本的区别。其后又加入大量不影响剧情的动画、电视或电影台词，或是模仿衣着及动作等等。此幅度的改编在制作之间评价好坏参半。不过，独特的作画和背景及镜头效果吸引了一定程度支持者，DVD销售获得丰厚盈利，而主题曲更被日本著名留言版2ch纳入组曲之内。",
