        "summary": "故事的女主角是与身为兽医的母亲相依为命的少女艾琳。有一天，被母亲照料的用于战斗的五头斗蛇一夜之间全部死亡，这被认为是照顾者的责任，导致她母亲遭到了活活地被斗蛇吞食的残暴刑法。艾琳虽然想救母亲，但幼小的她却差点和母亲一起成为了斗蛇的食物。幸好母亲吹奏的指笛控制的一头斗蛇将艾琳救了出去。成为了孤儿的艾琳得到了养蜂的老人琼的帮助，开始了独立的生活。在这期间，她对于生物及自身所生存的这个世界有了更深刻明析的看法。\n\n　　在山中碰到了翱翔在天空中的王兽。被决不亲近人，也不会被人类驯养的王兽之姿迷住了的艾琳，决心成为王兽的医生。于是她来到了卡扎姆王兽保护场开始学习。想要了解、帮助王兽、并与它们一起生活的艾琳成长得飞快。但她发现人类用来驱使王兽与斗蛇的无声兽笛会使动物们有短时间的僵硬。她开始对兽笛是否会对它们的身体产生负担一事产生了疑问。她开始试着去与王兽进行交流，用自己优秀的记忆力，将它们的发音正确记下来，并完美地再现。\n\n　　在越来越了解王兽的生态之谜时，虽然不是出于艾琳的本意，却自然地成为了真王与大公之外的又一新生力量。不久之后，艾琳就站在了能够左右王国命运的立场上……",
