        "summary": "电视动画《恶之华》改编自日本漫画家押见修造原作的同名漫画。在漫画杂志《别册少年Magazine》2012年12月号（11月9日发售）上，讲谈社正式公布了《恶之华》的“TV动画化决定”的消息。动画于2013年4月5日播放，全13话。  动画采用“rotoscope”的特殊技法，将拍摄的真人影像、现实风景描绘成2D图像，抛却了美型的外观，写实的图像更能深切地刻画出作品对社会人性的思考。  故事以“绝望”为主题，是一个变态少年，一个施虐女王还有一个乖乖女之间的扭曲变态的恋爱故事.春日是一个标准的文学青年，成日埋头于书本之间的他将法国著名诗人波德莱尔的代表作《恶之花》奉为圣经。在春日的内心里，同班女生佐伯奈奈子就是女神的象征，无奈于自己的平凡，春日只能依靠灼热的目光来传递心中的感情。 一次意外中，春日拾得了佐伯的体操服，鬼使神差之下他将还留有佐伯体香的体操服纳入了囊中，没想到，这一举动被班级里的“不良少女”仲村佐和完完全全的看在了眼里，而当春日想将体操服归还给佐伯之时他才发现，事态已经发展到了无法挽回的地步。利用春日的“弱点”，仲村和春日签订了所谓的“契约”，作为保守秘密的代价，春日不可以忤逆仲村的任何要求。恶之花静静的绽放，控制与被控制，一场三人之间的扭曲爱恋拉开了帷幕。",
